const jobs = $('BA: Treffer sammeln').all();
if (jobs.length === 1 && jobs[0].json.nothing) return [{ json: { nothing: true, _ba: jobs[0].json._ba } }];
const det = $input.all();
const out = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i].json; const d = (det[i] && det[i].json) || {};
  let data = {}, text = '';
  const raw = typeof d.data === 'string' ? d.data : (typeof d.body === 'string' ? d.body : '');
  if (d.statusCode === 200 && raw) {
    if (/^\s*[{\[]/.test(raw)) {
      try { data = JSON.parse(raw); } catch (e) { data = {}; }
      text = htmlToText(data.stellenangebotsBeschreibung || data.stellenbeschreibung || '');
    } else {
      // Öffentliche Detailseite: Hauptinhalt als Text
      const m = raw.match(/<main[\s\S]*?<\/main>/i) || raw.match(/<body[\s\S]*?<\/body>/i);
      text = htmlToText(m ? m[0] : raw)
        .split('\n').filter(l => !/^(Bitte anmelden|Merken|Teilen|Drucken|Zurück|Cookie|Sicherheitsabfrage|Zur Jobsuche|Startseite|Info zur Bewerbung|Vormerken|Notiz|Status Notiz|Bewerbungsstatus|PDF|Veröffentlichungsdatum)/i.test(l.trim())).join('\n');
    }
  }
  const extra = [j.facts || null, data.arbeitgeber ? 'Arbeitgeber: ' + data.arbeitgeber : null,
    data.arbeitsorte && data.arbeitsorte[0] ? 'Arbeitsort: ' + [data.arbeitsorte[0].ort, data.arbeitsorte[0].plz].filter(Boolean).join(' ') : null,
    data.arbeitszeitmodelle ? 'Arbeitszeit: ' + [].concat(data.arbeitszeitmodelle).join(', ') : null,
    data.befristung ? 'Befristung: ' + data.befristung : null].filter(Boolean).join('\n');
  out.push({ json: { title: data.titel || j.title, employer: data.arbeitgeber || j.employer, place: j.place,
    url: j.external_url || j.url, source: j.source, text: [extra, text].filter(Boolean).join('\n\n'), ext_id: j.ext_id, kw: j.kw } });
}
out[0].json._ba = jobs[0].json._ba;
return out;

