  fld2I3y1rPj2PLr5G: /^https?:\/\//i.test(j.url) ? j.url : null,
  fld67zsuzjVMWlHj4: j.source,
  fldtvWymZSuRBDJYc: 'Neu',
  fldGLAKchtHtA6nGP: today,
  fldSB3KbrVVJhGRBh: 'Vorprüfung: Anzeigentext konnte nicht geladen werden (' + (j.text ? j.text.length + ' Zeichen' : 'leer') + '). Link öffnen, Text in das Scorer-Formular einfügen oder Stelle verwerfen.',
  fldoRHnPAxTlxXJkQ: ['Job-Scout ' + today, j.place ? 'Ort: ' + j.place : null, j.text ? 'Textanfang: ' + j.text.slice(0, 300) : null].filter(Boolean).join('\n'),
};
for (const k of Object.keys(fields)) if (fields[k] === null) delete fields[k];
