// Kurze Telegram-Meldung: nur passende Stellen mit Link, Rest als Zahlen.
const first = $('Neue Stellen filtern').first().json;
const s = first._summary || {};
const allRuns = name => { const res = []; for (let r = 0; r < 500; r++) { let items; try { items = $(name).all(0, r); } catch (e) { break; } if (!items || !items.length) { if (r > 0) break; else continue; } res.push(...items); } return res; };
const short = t => String(t || '?').replace(/\s*\((?:m\/w\/d|w\/m\/d|d\/m\/w|m\/w\/div|f\/m\/d|all genders?)\)/gi, '').replace(/\s+/g, ' ').trim().slice(0, 70);
const AT = 'https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_JOBS_TABLE_ID/';
let top = [], near = 0, low = 0, excl = 0, vor = 0, errs = 0;
try { for (const it of allRuns('Scorer aufrufen')) { const r = it.json || {}; const sc = Number(r['Score']);
  if (r['Speicherfehler']) errs++;
  if (r['Harter Ausschluss'] && r['Harter Ausschluss'].length) { excl++; continue; }
  if (sc >= 75) top.push({ sc, t: short(r['Stelle']), id: r['Airtable-Datensatz'] }); else if (sc >= 65) near++; else low++; } } catch (e) {}
try { for (const it of allRuns('Vorprüfung speichern')) { const r = it.json || {}; if (r.error) errs++; vor += (r.records || []).length; } } catch (e) {}
top.sort((a, b) => b.sc - a.sc);
const day = $now.toFormat('dd.MM.');
if (!(s.processed > 0)) return [{ json: { text: `🔎 Job-Scout ${day}: keine neuen Stellen.` } }];
const lines = [`🔎 Job-Scout ${day} · ${s.processed} neu bewertet`];
if (top.length) { lines.push('', `✅ Passend (${top.length}):`); top.forEach((x, i) => lines.push(`${i + 1}. ${x.sc} · ${x.t}` + (x.id ? `\n   ${AT}${x.id}` : ''))); }
else lines.push('', 'Heute nichts ab 75.');
const rest = [near ? `${near} knapp darunter (65–74)` : null, low ? `${low} passen nicht` : null, excl ? `${excl} ausgeschlossen` : null, vor ? `${vor} ohne Text (Vorprüfung)` : null].filter(Boolean);
if (rest.length) lines.push('', rest.join(' · '));
if (s.skipped_over_cap) lines.push(`${s.skipped_over_cap} weitere kommen morgen.`);
if (errs) lines.push(`⚠️ ${errs} Speicherfehler – in n8n prüfen.`);
return [{ json: { text: lines.join('\n'), summary: s } }];
